#!/usr/bin/env python3

import time
import signal
import sys
import logging

import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import Adafruit_ADS1x15
import pigpio

# Configure logging
logging.basicConfig(
    level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s"
)

# Constants
MOTOR_DIR_PIN = 20
MOTOR_STEP_PIN = 21
MOTOR_CW = 1
MOTOR_CCW = 0
MOTOR_MS0_PIN = 14
MOTOR_MS1_PIN = 15
MOTOR_RESOLUTION = {
    "Full": (0, 0),
    "Half": (1, 0),
    "1/4": (0, 1),
    "1/8": (1, 1),
}
ADC_GAIN = 1
ADC_VOLTAGE_READING_MAX = 3.3
ADC_CHANNEL = 0
PWM_FREQUENCY = 500

class MotorController:
    """Controls the stepper motor via pigpio."""

    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin, pi_instance):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.pi = pi_instance
        self.resolution = "Full"
        self.direction = MOTOR_CCW
        self._setup_pins()

    def _setup_pins(self):
        """Sets up pigpio pins for motor control."""
        try:
            for pin in [self.dir_pin, self.step_pin, self.ms0_pin, self.ms1_pin]:
                self.pi.set_mode(pin, pigpio.OUTPUT)
        except pigpio.error as e:
            logging.error(f"pigpio error setting up motor pins: {e}")
            raise

    def set_resolution(self, resolution):
        """Sets the microstep resolution."""
        if resolution not in MotorController.RESOLUTION:
            logging.warning(f"Invalid resolution: {resolution}. Using Full.")
            resolution = "Full"
        try:
            for i, pin in enumerate([self.ms0_pin, self.ms1_pin]):
                self.pi.write(pin, MotorController.RESOLUTION[resolution][i])
            self.resolution = resolution
            logging.info(f"Set microstep resolution to: {resolution}")
        except pigpio.error as e:
            logging.error(f"pigpio error setting resolution: {e}")


    def set_direction(self, direction):
        """Sets the motor direction."""
        if direction not in [MOTOR_CW, MOTOR_CCW]:
            logging.warning("Invalid direction. Using CCW.")
            direction = MOTOR_CCW
        try:
            self.pi.write(self.dir_pin, direction)
            self.direction = direction
            logging.info(f"Set motor direction to: {'CW' if direction else 'CCW'}")
        except pigpio.error as e:
            logging.error(f"pigpio error setting direction: {e}")


    def set_pwm(self, duty_cycle):
        """Sets the PWM duty cycle for stepping the motor."""
        if not 0 <= duty_cycle <= 255:
            logging.warning("Duty cycle must be between 0 and 255.")
            return
        try:
            self.pi.set_PWM_dutycycle(self.step_pin, duty_cycle)
            self.pi.set_PWM_frequency(self.step_pin, PWM_FREQUENCY)
            logging.debug(f"Set PWM duty cycle to: {duty_cycle}")
        except pigpio.error as e:
            logging.error(f"pigpio error setting PWM: {e}")


    def stop(self):
        """Stops the motor."""
        try:
            self.pi.set_PWM_dutycycle(self.step_pin, 0)
            logging.info("Motor stopped.")
        except pigpio.error as e:
            logging.error(f"pigpio error stopping motor: {e}")


    def close(self):
        """Releases pigpio resources."""
        self.pi.stop()


class SensorManager:
    """Manages accelerometer and magnetometer readings."""

    def __init__(self, i2c):
        self.accelerometer = None
        self.magnetometer = None
        try:
            self.accelerometer = adafruit_lsm303_accel.LSM303_Accel(i2c)
            self.magnetometer = adafruit_lsm303dlh_mag.LSM303DLH_Mag(i2c)
            logging.info("Accelerometer and magnetometer initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing sensors: {e}")
            self.accelerometer = None
            self.magnetometer = None

    def get_acceleration(self):
        """Returns accelerometer readings in m/s^2."""
        if self.accelerometer is None:
            return None
        try:
            accel_x, accel_y, accel_z = self.accelerometer.acceleration
            return accel_x, accel_y, accel_z
        except Exception as e:
            logging.error(f"Error reading accelerometer: {e}")
            return None

    def get_magnetic_field(self):
        """Returns magnetometer readings in gauss."""
        if self.magnetometer is None:
            return None
        try:
            mag_x, mag_y, mag_z = self.magnetometer.magnetic
            return mag_x, mag_y, mag_z
        except Exception as e:
            logging.error(f"Error reading magnetometer: {e}")
            return None


    def get_heading(self):
        """Calculates and returns the heading in degrees."""
        if self.magnetometer is None:
            return None

        magnetic_field = self.get_magnetic_field()
        if magnetic_field is None:
            return None

        mag_x, mag_y, _ = magnetic_field
        try:
            heading = 360 * math.atan2(mag_y, mag_x) / (2 * math.pi)
            if heading < 0:
                heading += 360
            return heading
        except Exception as e:
            logging.error(f"Error calculating heading: {e}")
            return None


    def get_inclination(self):
        """Calculates and returns inclination angles (XZ, YZ)."""
        if self.accelerometer is None:
            return None

        acceleration = self.get_acceleration()
        if acceleration is None:
            return None

        accel_x, accel_y, accel_z = acceleration
        try:
            xz_angle = math.degrees(math.atan2(accel_x, accel_z))
            yz_angle = math.degrees(math.atan2(accel_y, accel_z))
            return xz_angle, yz_angle
        except Exception as e:
            logging.error(f"Error calculating inclination: {e}")
            return None


class ADCManager:
    """Manages ADC readings and voltage conversions."""

    def __init__(self, adc, gain=ADC_GAIN):
        self.adc = adc
        self.gain = gain

    def read_channel(self, channel):
        """Reads and returns the voltage from the specified ADC channel."""
        try:
            raw_value = self.adc.read_adc(channel, gain=self.gain)
            voltage = (raw_value * ADC_VOLTAGE_READING_MAX) / 1647  # For 12 bit ADC
            return voltage
        except Exception as e:
            logging.error(f"Error reading ADC channel {channel}: {e}")
            return None

    def get_duty_cycle(self, channel):
        """Converts voltage to PWM duty cycle (0-255)."""
        voltage = self.read_channel(channel)
        if voltage is None:
            return None

        try:
            duty_cycle = (voltage / ADC_VOLTAGE_READING_MAX) * 255
            return int(duty_cycle)
        except Exception as e:
            logging.error(f"Error converting voltage to duty cycle: {e}")
            return None


class GracefulKiller:
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""

    kill_now = False

    def __init__(self):
        signal.signal(signal.SIGINT, self.exit_gracefully)
        signal.signal(signal.SIGTERM, self.exit_gracefully)

    def exit_gracefully(self, signum, frame):
        self.kill_now = True


if __name__ == "__main__":
    import math

    killer = GracefulKiller()

    try:
        # Initialize pigpio
        pi = pigpio.pi()
        if not pi.connected:
            raise pigpio.error("Failed to connect to pigpio daemon.")

        # Initialize I2C bus
        i2c = busio.I2C(board.SCL, board.SDA)

        # Initialize motor controller
        motor = MotorController(
            MOTOR_DIR_PIN,
            MOTOR_STEP_PIN,
            MOTOR_MS0_PIN,
            MOTOR_MS1_PIN,
            pi,
        )
        motor.set_resolution("Full")
        motor.set_direction(MOTOR_CCW)

        # Initialize sensor manager
        sensors = SensorManager(i2c)

        # Initialize ADC manager
        adc = ADCManager(Adafruit_ADS1x15.ADS1015())

        # Main loop
        while not killer.kill_now:
            # Read and print ADC values
            duty_cycle = adc.get_duty_cycle(ADC_CHANNEL)
            if duty_cycle is not None:
                logging.info(f"ADC Channel {ADC_CHANNEL}: {duty_cycle}")
                motor.set_pwm(duty_cycle)

            # Read and print sensor readings
            acceleration = sensors.get_acceleration()
            magnetic_field = sensors.get_magnetic_field()
            heading = sensors.get_heading()
            inclination = sensors.get_inclination()

            if acceleration:
                accel_x, accel_y, accel_z = acceleration
                logging.info(f"Acceleration: x={accel_x:.2f}, y={accel_y:.2f}, z={accel_z:.2f} m/s^2")

            if magnetic_field:
                mag_x, mag_y, mag_z = magnetic_field
                logging.info(f"Magnetic Field: x={mag_x:.2f}, y={mag_y:.2f}, z={mag_z:.2f} gauss")

            if heading is not None:
                logging.info(f"Heading: {heading:.2f} degrees")

            if inclination:
                xz_angle, yz_angle = inclination
                logging.info(f"Inclination: XZ={xz_angle:.2f} degrees, YZ={yz_angle:.2f} degrees")

            time.sleep(1.0)

    except pigpio.error as e:
        logging.error(f"pigpio error: {e}")
    except Exception as e:
        logging.exception(f"An unexpected error occurred: {e}")
    finally:
        logging.info("Shutting down...")
        if 'motor' in locals():
            motor.stop()
        if 'pi' in locals():
            pi.stop()

