import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15 import ADSSuperClass

# Constants for I2C bus and ADS1115 address
I2C_BUS = 1
ADS1115_ADDRESS = 0x48

# ADS1115 gain setting (adjust as needed)
GAIN = ADS.GAIN_FOUR_096V

def initialize_adc():
    """Initializes the I2C bus and ADS1115 ADC."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        adc = ADS.ADS1115(i2c_bus, address=ADS1115_ADDRESS)
        return adc
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def read_adc_channels(adc):
    """Reads all 4 ADC channels and returns the raw values."""
    try:
        return [adc.read_adc(i, gain=GAIN) for i in range(4)]
    except Exception as e:
        print(f"Error reading ADC channel: {e}")
        return None

def format_output(channel_values):
    """Formats the raw ADC values into a table for printing."""
    if not channel_values:
        return
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*channel_values))

def print_header():
    """Prints the header row for the ADC table."""
    print('| {0:>6} | {1:>6} | {2:>6} | {3:>6} |'.format(*range(4)))
    print('-' * 37)

def main():
    """Main function to continuously read and print ADC values."""
    adc = initialize_adc()
    if not adc:
        return

    try:
        while True:
            channel_values = read_adc_channels(adc)
            if channel_values:
                print('ADC Result:')
                print_header()
                format_output(channel_values)
                print('\n')
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

