    try:
        video_camera, config = initialize_camera_and_config()
        config.set_classifier(config.classifier_name)  # Load classifier during initialization
    except Exception:
        logger.critical("Unrecoverable initialization failure. Exiting.")
        exit(1)  # Exit the application if initialization fails


def cleanup() -> None:
    """Releases camera and other resources."""
    logger.info("Cleaning up resources.")
