import RPi.GPIO as GPIO
import time
import datetime
import os
import signal
import sys
import random
import speech_recognition as sr
import picamera2
import adafruit_dht

# Configuration
LIGHT_PIN = 17  # GPIO pin for lights
DHT_PIN = 4  # GPIO pin for DHT11 sensor (BCM numbering)
WAKE_WORD = "Greenhouse"

# Global variables
lights_on = False
simulated_temperature = 25.0

# Initialize GPIO (or simulate if unavailable)
try:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT)
    print("GPIO initialized successfully.")
except Exception as e:
    print(f"Error initializing GPIO: {e}. Running in simulation mode.")
    GPIO = None  # Disable GPIO for simulation

# Initialize DHT sensor (or simulate if unavailable)
try:
    dht_device = adafruit_dht.DHT11(DHT_PIN)
    print("DHT sensor initialized successfully.")
except Exception as e:
    print(f"Error initializing DHT sensor: {e}. Running in simulation mode.")
    dht_device = None # Disable DHT for simulation

# Initialize camera (or simulate if unavailable)
try:
    camera = picamera2.Picamera2()
    camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
    camera.start()
    print("Camera initialized successfully.")
except Exception as e:
    print(f"Error initializing camera: {e}. Running in simulation mode.")
    camera = None # Disable camera for simulation

# Function to turn lights on
def turn_lights_on():
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
    else:
        print("Simulating: Turning lights on")
    lights_on = True

# Function to turn lights off
def turn_lights_off():
    global lights_on
    if GPIO:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
    else:
        print("Simulating: Turning lights off")
    lights_on = False

# Function to read temperature from DHT sensor
def read_temperature():
    global simulated_temperature
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT sensor returned None. Using simulated temperature.")
                return simulated_temperature
        except Exception as e:
            print(f"Error reading temperature: {e}. Using simulated temperature.")
            return simulated_temperature
    else:
        # Simulate temperature reading
        simulated_temperature = random.uniform(15, 35)
        return simulated_temperature

# Function to capture image with camera
def capture_image():
    if camera:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        try:
            camera.capture_file(filename)
            print(f"Image captured: {filename}")
        except Exception as e:
            print(f"Error capturing image: {e}")
    else:
        print("Simulating: Capturing image")

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("Exiting program...")
    if GPIO:
        GPIO.cleanup()
    if camera:
        camera.close()
    sys.exit(0)

# Register signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main program loop
def main():
    r = sr.Recognizer()
    mic = sr.Microphone()

    print("Greenhouse control system started. Say 'Greenhouse' to activate.")

    while True:
        with mic as source:
            r.adjust_for_ambient_noise(source)
            try:
                audio = r.listen(source, timeout=5) # Listen for up to 5 seconds
            except sr.WaitTimeoutError:
                continue # Continue to the next iteration if no speech is detected

        try:
            # Recognize speech using Google Web Speech API
            text = r.recognize_google(audio)
            print(f"You said: {text}")

            if WAKE_WORD in text:
                print("Wake word detected!")
                if "turn on the lights" in text:
                    turn_lights_on()
                    print("Lights turned on.")
                elif "turn off the lights" in text:
                    turn_lights_off()
                    print("Lights turned off.")
                elif "what is the temperature" in text:
                    temperature = read_temperature()
                    print(f"The temperature is {temperature:.1f} degrees Celsius.")
                elif "take a picture" in text:
                    capture_image()
                else:
                    print("Unknown command.")

        except sr.UnknownValueError:
            print("Could not understand audio")
        except sr.RequestError as e:
            print(f"Could not request results from Google Speech Recognition service; {e}")
        except Exception as e:
            print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

