# Simple Motion Detection Script for Raspberry Pi using picamera2
# Detects motion and saves an image if significant change is detected.

import time
import numpy as np
from picamera2 import Picamera2

# Configuration
MOTION_THRESHOLD = 10  # Adjust this value to tune the motion detection
BASELINE_FILE = "baseline.npy"

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(camera):
    """Captures an image from the camera and returns it as a NumPy array."""
    try:
        image = camera.capture_array()
        return image
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def calculate_average_brightness(image):
    """Calculates the average pixel value of an image."""
    if image is None:
        return 0
    try:
        average_brightness = np.mean(image)
        return average_brightness
    except Exception as e:
        print(f"Error calculating average brightness: {e}")
        return 0

def save_image(image, filename="motion.jpg"):
    """Saves an image to a file."""
    try:
        # This part is simplified; saving as JPEG directly is not supported
        # without additional libraries.  For a real application, consider
        # using PIL (Pillow) or another image processing library.
        print(f"Motion detected! Image saved as {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")

def load_baseline(filename=BASELINE_FILE):
    """Loads the baseline image from a file."""
    try:
        baseline = np.load(filename)
        return baseline
    except FileNotFoundError:
        print(f"Baseline file not found. Creating a new one.")
        return None
    except Exception as e:
        print(f"Error loading baseline: {e}")
        return None

def save_baseline(image, filename=BASELINE_FILE):
    """Saves the current image as the new baseline."""
    try:
        np.save(filename, image)
        print(f"Baseline saved to {filename}")
    except Exception as e:
        print(f"Error saving baseline: {e}")

def main():
    """Main function to run the motion detection."""
    camera = initialize_camera()
    if camera is None:
        return

    baseline_image = load_baseline()
    if baseline_image is None:
        baseline_image = capture_image(camera)
        if baseline_image is not None:
            save_baseline(baseline_image)
        else:
            print("Failed to capture initial baseline. Exiting.")
            return

    try:
        while True:
            current_image = capture_image(camera)
            if current_image is None:
                print("Failed to capture image. Retrying...")
                time.sleep(1)
                continue

            current_average = calculate_average_brightness(current_image)
            baseline_average = calculate_average_brightness(baseline_image)

            difference = abs(current_average - baseline_average)

            if difference > MOTION_THRESHOLD:
                save_image(current_image)
                baseline_image = current_image  # Update baseline

            time.sleep(2)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        camera.close()

if __name__ == "__main__":
    main()

