import time
import sys
import signal
from gpiozero import PWMOutputDevice
from typing import List, Callable

# Constants
DEFAULT_PWM_PIN = 17
DEFAULT_PWM_VALUE = 1.0
POLL_INTERVAL = 5
TEMPERATURE_FILE = "/sys/class/thermal/thermal_zone0/temp"

# Configuration (adjust these values as needed)
CONFIG = {
    "thresholds": [45.0, 45.0, 50.0, 55.0, 65.0],  # Degrees Celsius
    "pwm_values": [0.4, 0.4, 0.6, 0.8, 1.0],  # Corresponding PWM values (0.0 to 1.0)
    "default_pwm": DEFAULT_PWM_VALUE, # PWM value when below all thresholds
    "log_function": print # Function to use for logging (can be replaced with a more sophisticated logger)
}


def read_temperature() -> float:
    """Reads the CPU temperature from the system file."""
    try:
        with open(TEMPERATURE_FILE, "r") as f:
            temp_ms = f.read().strip()
            temperature = float(temp_ms) / 1000.0
            return temperature
    except (FileNotFoundError, IOError, ValueError) as e:
        raise RuntimeError(f"Error reading temperature: {e}")


def calculate_pwm(temperature: float) -> float:
    """Calculates the desired PWM value based on the temperature."""
    if temperature < CONFIG["thresholds"][0]:
        return CONFIG["pwm_values"][0]  # Default PWM if below lowest threshold
    for i in range(len(CONFIG["thresholds"]) - 1):
        if CONFIG["thresholds"][i] <= temperature < CONFIG["thresholds"][i+1]:
            return CONFIG["pwm_values"][i+1] # Linear interpolation
    return CONFIG["pwm_values"][-1] # Max PWM if above highest threshold


def safe_pwm_set(fan: PWMOutputDevice, pwm_value: float) -> None:
    """Sets the fan PWM value, handling potential errors."""
    try:
        fan.value = pwm_value
    except Exception as e:
        raise RuntimeError(f"Error setting PWM value: {e}")


def main_loop(fan: PWMOutputDevice) -> None:
    """Main loop to continuously control the fan."""
    try:
        while True:
            try:
                temperature = read_temperature()
                CONFIG["log_function"](f"Temperature: {temperature:.2f}°C")
                pwm_value = calculate_pwm(temperature)
                CONFIG["log_function"](f"PWM: {pwm_value:.2f}")
                safe_pwm_set(fan, pwm_value)
                time.sleep(POLL_INTERVAL)
            except RuntimeError as e:
                CONFIG["log_function"](f"Error: {e}")
                time.sleep(POLL_INTERVAL) # Avoid spamming errors
    except Exception as e: # Catch any unexpected errors
        CONFIG["log_function"](f"Unexpected error in main loop: {e}")


def cleanup(signal_number: int, frame, fan: PWMOutputDevice) -> None:
    """Handles cleanup and exit."""
    CONFIG["log_function"](f"Received signal {signal_number}. Exiting gracefully...")
    try:
        safe_pwm_set(fan, CONFIG["default_pwm"])  # Set fan to default PWM
        fan.close() # Release GPIO resources
    except Exception as e:
        CONFIG["log_function"](f"Error during cleanup: {e}")
    sys.exit(0)


def validate_configuration() -> None:
    """Validates the configuration parameters."""
    if len(CONFIG["thresholds"]) != len(CONFIG["pwm_values"]):
        raise ValueError("Thresholds and PWM values lists must have the same length.")
    if any(not 0.0 <= pwm <= 1.0 for pwm in CONFIG["pwm_values"]):
        raise ValueError("All PWM values must be between 0.0 and 1.0.")


def main() -> None:
    """Main function to initialize and run the fan control."""
    validate_configuration()

    try:
        fan = PWMOutputDevice(DEFAULT_PWM_PIN)
        safe_pwm_set(fan, CONFIG["default_pwm"]) # Initial fan speed
        CONFIG["log_function"](f"Fan initialized on pin {DEFAULT_PWM_PIN} with PWM {CONFIG['default_pwm']}")
    except Exception as e:
        CONFIG["log_function"](f"Error initializing fan: {e}")
        sys.exit(1) # Exit if fan initialization fails


    signal.signal(signal.SIGINT, lambda signum, frame: cleanup(signum, frame, fan))
    signal.signal(signal.SIGTERM, lambda signum, frame: cleanup(signum, frame, fan))

    main_loop(fan)


if __name__ == "__main__":
    main()

