import cv2
import pyzbar.pyzbar as pyzbar
import datetime
import csv
import time
import os

# Constants
CAMERA_INDEX = 0  # Index of the USB camera
LOG_FILE = 'inventory_log.csv'
ERROR_LOG = 'error_log.txt'

def initialize_camera(camera_index):
    """Initializes the camera and returns the capture object."""
    try:
        capture = cv2.VideoCapture(camera_index)
        if not capture.isOpened():
            raise Exception("Could not open camera")
        return capture
    except Exception as e:
        log_error(f"Camera initialization failed: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes from a frame and returns the item ID."""
    try:
        decoded_objects = pyzbar.decode(frame)
        if decoded_objects:
            item_id = decoded_objects[0].data.decode('utf-8')
            return item_id
        return None
    except Exception as e:
        log_error(f"QR code decoding failed: {e}")
        return None

def validate_item_id(item_id):
    """Validates the item ID to ensure it's alphanumeric."""
    try:
        if not item_id.isalnum():
            raise ValueError("Item ID must be alphanumeric")
        return True
    except Exception as e:
        log_error(f"Item ID validation failed: {e}")
        return False

def log_data(camera_id, item_id, capture_time):
    """Logs the data to the CSV file."""
    try:
        file_exists = os.path.isfile(LOG_FILE)
        with open(LOG_FILE, 'a', newline='') as csvfile:
            fieldnames = ['camera_id', 'item_id', 'capture_time']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            if not file_exists:
                writer.writeheader()
            writer.writerow({'camera_id': camera_id, 'item_id': item_id, 'capture_time': capture_time})
    except Exception as e:
        log_error(f"Data logging failed: {e}")

def log_error(error_message):
    """Logs error messages to the error log file."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG, 'a') as error_file:
            error_file.write(f"{timestamp} - {error_message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}")

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera(CAMERA_INDEX)
    if camera is None:
        print("Failed to initialize camera. Exiting.")
        return

    try:
        while True:
            ret, frame = camera.read()
            if not ret:
                log_error("Failed to capture frame")
                time.sleep(0.2)
                continue

            item_id = decode_qr_code(frame)
            if item_id:
                if validate_item_id(item_id):
                    capture_time = datetime.datetime.now().isoformat()
                    log_data('Camera 1', item_id, capture_time)
                    print(f"Item ID: {item_id}, Captured at: {capture_time}")
                else:
                    print(f"Invalid Item ID: {item_id}")

            time.sleep(0.2)

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Release the camera and close all OpenCV windows
        camera.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

