def signal_handler(sig, frame):
    """Handles termination signals (e.g., Ctrl+C)."""
    print("\nExiting program...")
    if i2c_bus:
        try:
            i2c_bus.close()
            print("I2C bus closed successfully.")
        except Exception as e:
            print(f"Error closing I2C bus: {e}")
    sys.exit(0)

# Register the signal handler for SIGINT (Ctrl+C)
signal.signal(signal.SIGINT, signal_handler)

def initialize_i2c_bus(bus_number):
    """Initializes the I2C bus."""
    global i2c_bus
    try:
        i2c_bus = smbus.SMBus(bus_number)
        print(f"I2C bus {bus_number} initialized successfully.")
        return True
    except Exception as e:
        print(f"Error initializing I2C bus {bus_number}: {e}")
        return False

def read_cpu_temperature():
    """Reads the CPU temperature from the Raspberry Pi."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            temp_millidegrees = int(f.read())
        temperature_celsius = temp_millidegrees / 1000.0
        return temperature_celsius
    except FileNotFoundError:
        print("Error: Could not read CPU temperature. File not found.")
        return None
    except PermissionError:
        print("Error: Could not read CPU temperature. Permission denied.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None

def main():
    """Main function to read and display CPU temperature."""
    if not initialize_i2c_bus(I2C_BUS):
        print("Failed to initialize I2C bus. Exiting.")
        sys.exit(1)

    try:
        while True:
            temperature = read_cpu_temperature()
            if temperature is not None:
                print(f"CPU Temperature: {temperature:.1f} °C")
            time.sleep(2)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the I2C bus is closed on exit
        if i2c_bus:
            try:
                i2c_bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

