#!/usr/bin/env python3
import time
import signal
import subprocess
from gpiozero import PWMOutputDevice, CleanupError
from functools import partial

# Constants for PWM frequency, fan pin, and temperature thresholds
PWM_FREQUENCY = 100
FAN_GPIO_PIN = 14
TEMPERATURE_CHECK_INTERVAL = 5
DUTY_CYCLE_MAPPING = {
    70: 100,
    60: 85,
    50: 70,
    40: 50,
    32: 25,
    25: 15,
    0: 0,
}


def get_cpu_temperature():
    """Reads the CPU temperature using vcgencmd.

    Returns:
        float: CPU temperature in degrees Celsius.

    Raises:
        RuntimeError: If vcgencmd fails to execute.
    """
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, check=True, text=True)
        return float(result.stdout.split('=')[1].split('\'')[0])
    except (subprocess.CalledProcessError, IndexError, ValueError) as e:
        raise RuntimeError(f"Failed to get temperature: {e}")


def set_fan_speed(fan, duty_cycle):
    """Sets the fan speed using PWM.

    Args:
        fan: The PWMOutputDevice instance.
        duty_cycle: The duty cycle (0-100).
    """
    try:
        fan.value = duty_cycle / 100
    except Exception as e:
        raise RuntimeError(f"Failed to set fan speed: {e}")


def control_fan(fan, temperature):
    """Determines the appropriate fan speed based on temperature.

    Args:
        fan: The PWMOutputDevice instance.
        temperature: The current CPU temperature.
    """
    try:
        ideal_duty_cycle = next(
            (duty_cycle for temp, duty_cycle in sorted(DUTY_CYCLE_MAPPING.items(), reverse=True) if temperature > temp),
            0
        )
        set_fan_speed(fan, ideal_duty_cycle)
        print(f"Temperature: {temperature:.2f}°C, Fan Speed: {ideal_duty_cycle:.2f}%")
    except RuntimeError as e:
        print(f"Error: {e}")
        # Consider a fallback strategy, e.g., setting fan to full speed or off


def main_loop(fan):
    """Main loop to continuously monitor temperature and adjust fan speed."""
    while True:
        try:
            temperature = get_cpu_temperature()
            control_fan(fan, temperature)
            time.sleep(TEMPERATURE_CHECK_INTERVAL)
        except RuntimeError as e:
            print(f"Error in main loop: {e}")
            time.sleep(TEMPERATURE_CHECK_INTERVAL)  # Avoid excessive error printing


def cleanup(fan):
    """Releases resources and ensures the fan is stopped."""
    print("Cleaning up and exiting...")
    try:
        fan.close()  # Stop PWM generation
    except CleanupError as e:
        print(f"Cleanup error: {e}")


def signal_handler(sig, frame, fan):
    """Handles signals for graceful shutdown."""
    print("\nExiting gracefully...")
    cleanup(fan)
    exit(0)


def initialize_fan(pin):
    """Initializes the PWMOutputDevice."""
    try:
        return PWMOutputDevice(pin, frequency=PWM_FREQUENCY)
    except Exception as e:
        raise RuntimeError(f"Failed to initialize fan: {e}")


def main():
    """Main function to run the fan control."""
    try:
        fan = initialize_fan(FAN_GPIO_PIN)
        handler = partial(signal_handler, fan=fan)
        signal.signal(signal.SIGINT, handler)
        signal.signal(signal.SIGTERM, handler)
        main_loop(fan)
    except RuntimeError as e:
        print(f"Fatal error: {e}")
        exit(1)


if __name__ == "__main__":
    main()

