            if channel_state is not None:
                for state_key, value in channel_state.items():
                    self.channel_info[state_key]['state'] = value

                all_states = [item['state'] for item in self.channel_info.values()]
                error_detected = False
                for state in all_states:
                    if state is not None:
                        error_detected |= state > 0

                self.set_error_output(error_detected)

        except KeyError as e:
            logging.error(f"Error updating error output: {e}")


    def set_error_output(self, error_state):
        """Sets the error output pin to the specified state."""
        if not self.config.get('use_error_output'):
