                    self.error_output.value = error_state

            if error_state != self.global_err_state:
                logging.info(f"Error output set to: {error_state}")
                self.global_err_state = error_state

        except Exception as e:
            logging.error(f"Error setting error output: {e}")

    def cleanup(self):
        """Releases resources held by the PID handler."""
        if self.chip:
            self.chip.stop()
        elif self.pwm_chip:
