class SubscriptionHandler:
    """Handles subscriptions to data streams and manages callbacks."""

    def __init__(self):
        self.subscriptions = {}  # Dictionary to store subscriptions: {stream_filter: [callback_info]}
        self.channel_info = {}  # store channel specific information
        self.subscriber_socket = None

    def handle_command(self, command, subscriber_socket):
        """Processes commands to manage subscriptions and control channels."""
        self.subscriber_socket = subscriber_socket
        try:
            action = command.get('action')
            if action == 'SUBSCRIBE':
                self._subscribe(command)
            elif action == 'UNSUBSCRIBE':
                self._unsubscribe(command)
            elif action == 'UPDATE_KW':
                self._update_keywords(command)
            elif action == 'REMOVE_ALL_CBS':
                self._remove_all_callbacks(command)
            elif action == 'RESET':
                self._reset_channel(command)
            elif action == 'RESET_ALL':
                self._reset_all_channels(command)
            elif action == 'MUTE':
                self._mute_channel(command)
            elif action == 'UNMUTE':
                self._unmute_channel(command)
            elif action == 'MUTE_ALL':
                self._mute_all_channels(command)
            elif action == 'UNMUTE_ALL':
                self._unmute_all_channels(command)
            elif action == 'PAUSE_ALL':
                self._pause_all_channels(command)
            elif action == 'RESTART_ALL':
                self._restart_all_channels(command)
            elif action == 'TERMINATE':
                self._terminate_channel(command)
            elif action == 'RESTART':
                self._restart_channel(command)
            else:
                raise ValueError(f"Invalid action: {action}")
        except (KeyError, ValueError) as e:
            logging.error(f"Error processing command: {e}")
            return str(e)
        return None


    def _subscribe(self, command):
        """Subscribes to a data stream."""
        stream_filter = command['stream_filter']
        channel_id = command['id']
        callback = command['callback']

        if stream_filter not in self.subscriptions:
            self.subscriptions[stream_filter] = []
            if self.subscriber_socket:  # Check if subscriber_socket is initialized
                self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_filter)
            logging.info(f"Subscribed to stream filter: {stream_filter}")

        self.subscriptions[stream_filter].append({
            'callback': callback,
            'state': {},
            'control': {'alert': True, 'pause': False},
            'id': channel_id
        })
        self.channel_info[channel_id] = {'kwargs': {}, 'state': {}, 'control': {'alert': True, 'pause': False}}

        logging.debug(f"Subscription added: {stream_filter}, Channel ID: {channel_id}")


    def _unsubscribe(self, command):
        """Unsubscribes from a data stream."""
        stream_filter = command['stream_filter']

        if stream_filter in self.subscriptions:
            if self.subscriber_socket:
                self.subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
            del self.subscriptions[stream_filter]
            logging.info(f"Unsubscribed from stream filter: {stream_filter}")
        else:
            logging.warning(f"Not subscribed to stream filter: {stream_filter}")


    def _update_keywords(self, command):
        """Updates the keywords used by a specific channel."""
        stream_filter = command['stream_filter']
        channel_id = command['id']
        keywords = command['keywords']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                if callback_info['id'] == channel_id:
                    callback_info['keywords'] = keywords
                    logging.debug(f"Keywords updated for channel {channel_id} on stream {stream_filter}")
                    break  # Stop searching once the channel is found
            else:
                logging.warning(f"Channel {channel_id} not found on stream {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")


    def _remove_all_callbacks(self, command):
        """Removes all callbacks for a specific stream filter."""
        stream_filter = command['stream_filter']
        try:
            del self.subscriptions[stream_filter]
            if self.subscriber_socket:
                self.subscriber_socket.setsockopt_string(zmq.UNSUBSCRIBE, stream_filter)
            logging.info(f"All callbacks removed for stream filter: {stream_filter}")
        except KeyError:
            logging.warning(f"No callbacks found for stream filter: {stream_filter}")


    def _reset_channel(self, command):
        """Resets the state of a specific channel."""
        stream_filter = command['stream_filter']
        channel_id = command['id']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                if callback_info['id'] == channel_id:
                    callback_info['state'] = {}
                    logging.debug(f"State reset for channel {channel_id} on stream {stream_filter}")
                    break
            else:
                logging.warning(f"Channel {channel_id} not found on stream {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")

    def _reset_all_channels(self, command):
        """Resets the state of all channels for a specific stream filter."""
        stream_filter = command['stream_filter']
        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                callback_info['state'] = {}
            logging.info(f"State reset for all channels on stream filter: {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")


    def _mute_channel(self, command):
        """Mutes a specific channel."""
        self._toggle_channel_alert(command, False)

    def _unmute_channel(self, command):
        """Unmutes a specific channel."""
        self._toggle_channel_alert(command, True)

    def _mute_all_channels(self, command):
        """Mutes all channels for a specific stream filter."""
        self._toggle_all_channels_alert(command, False)

    def _unmute_all_channels(self, command):
        """Unmutes all channels for a specific stream filter."""
        self._toggle_all_channels_alert(command, True)

    def _toggle_channel_alert(self, command, alert_state):
        """Toggles the alert state for a specific channel."""
        stream_filter = command['stream_filter']
        channel_id = command['id']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                if callback_info['id'] == channel_id:
                    callback_info['control']['alert'] = alert_state
                    logging.debug(f"Alert state changed to {alert_state} for channel {channel_id} on stream {stream_filter}")
                    break
            else:
                logging.warning(f"Channel {channel_id} not found on stream {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")

    def _toggle_all_channels_alert(self, command, alert_state):
        """Toggles the alert state for all channels on a specific stream filter."""
        stream_filter = command['stream_filter']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                callback_info['control']['alert'] = alert_state
            logging.info(f"Alert state changed to {alert_state} for all channels on stream filter: {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")

    def _pause_all_channels(self, command):
        """Pauses all channels for a specific stream filter."""
        self._toggle_all_channels_pause(command, True)

    def _restart_all_channels(self, command):
        """Restarts all paused channels for a specific stream filter."""
        self._toggle_all_channels_pause(command, False)

    def _toggle_all_channels_pause(self, command, pause_state):
        """Toggles the pause state for all channels on a specific stream filter."""
        stream_filter = command['stream_filter']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                callback_info['control']['pause'] = pause_state
            logging.info(f"Pause state changed to {pause_state} for all channels on stream filter: {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")

    def _terminate_channel(self, command):
        """Terminates a specific channel."""
        self._modify_channel_termination(command, True)

    def _restart_channel(self, command):
        """Restarts a terminated channel."""
        self._modify_channel_termination(command, False)

    def _modify_channel_termination(self, command, terminated):
        """Modifies the termination state of a specific channel."""
        stream_filter = command['stream_filter']
        channel_id = command['id']

        if stream_filter in self.subscriptions:
            for callback_info in self.subscriptions[stream_filter]:
                if callback_info['id'] == channel_id:
                    callback_info['control']['terminate'] = terminated
                    logging.debug(f"Termination state changed to {terminated} for channel {channel_id} on stream {stream_filter}")
                    break
            else:
                logging.warning(f"Channel {channel_id} not found on stream {stream_filter}")
        else:
            logging.warning(f"Stream filter {stream_filter} not found")

    def get_channel_info(self):
        """Returns a copy of the channel information."""
        return self.channel_info.copy()


