# A simple script to authenticate fingerprints using an Adafruit Fingerprint sensor on Raspberry Pi 5.
# Designed for STEM education, emphasizing clarity and robustness.

import time
import board
import busio
import adafruit_fingerprint

# Define the I2C address of the fingerprint sensor
FINGERPRINT_I2C_ADDRESS = 0x26

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_fingerprint_sensor(i2c_bus):
    """Initializes the fingerprint sensor."""
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
        return fingerprint_sensor
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor: {e}")
        return None

def get_fingerprint_image(fingerprint_sensor):
    """Acquires a fingerprint image from the sensor."""
    try:
        return fingerprint_sensor.get_image()
    except Exception as e:
        print(f"Error getting image: {e}")
        return None

def convert_image_to_template(fingerprint_sensor, image):
    """Converts the image to a template."""
    try:
        return fingerprint_sensor.image_2_tz(1)
    except Exception as e:
        print(f"Error converting image to template: {e}")
        return None

def search_fingerprint_database(fingerprint_sensor, template):
    """Searches the fingerprint database for a match."""
    try:
        return fingerprint_sensor.finger_search()
    except Exception as e:
        print(f"Error searching fingerprint database: {e}")
        return None

def authenticate_fingerprint(fingerprint_sensor):
    """Authenticates the fingerprint against the database."""
    image = get_fingerprint_image(fingerprint_sensor)
    if image is None:
        return False

    template = convert_image_to_template(fingerprint_sensor, image)
    if template is None:
        return False

    result = search_fingerprint_database(fingerprint_sensor, template)
    if result.finger_id != 0xFFFFFFFF:
        print(f'Access Granted for Fingerprint ID: {result.finger_id} with Confidence: {result.confidence}')
        return True
    else:
        print('Access Denied')
        return False

def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        return

    try:
        while True:
            if authenticate_fingerprint(fingerprint_sensor):
                time.sleep(1)  # Delay to prevent rapid re-authentication
            else:
                time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for I2C or the sensor object in this library
        # but good practice to include a cleanup section in case future libraries require it
        print("Program finished.")

if __name__ == "__main__":
    main()

