# Ambient light sensor and LED brightness controller for Raspberry Pi
# Reads light from a TSL2561 sensor and adjusts LED brightness
import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO
from gpiozero import PWMLED
from adafruit_blinka.microcontroller.raspberry_pi import pwm

# Define the GPIO pin for the LED
LED_GPIO_PIN = 18

# I2C address of the TSL2561 sensor
TSL2561_ADDRESS = 0x39

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus)
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2561 sensor: {e}")
        return None

def initialize_led():
    """Initialize the LED with hardware PWM."""
    try:
        led = PWMLED(LED_GPIO_PIN, pin_factory=pwm)
        led.pwm.frequency = 1000  # Set PWM frequency
        return led
    except Exception as e:
        print(f"Error initializing LED: {e}")
        return None

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        lux_value = sensor.lux
        return lux_value
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def calculate_brightness(lux_value):
    """Map the light level to a brightness percentage."""
    if lux_value is None:
        return 0.0
    return max(0.0, min(100.0, lux_value / 10))

def set_led_brightness(led, brightness_percentage):
    """Set the LED brightness based on the calculated percentage."""
    try:
        led.value = brightness_percentage / 100.0
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to read light and control LED brightness."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_sensor(i2c_bus)
    if light_sensor is None:
        return

    led_device = initialize_led()
    if led_device is None:
        return

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                led_brightness = calculate_brightness(light_level)
                set_led_brightness(led_device, led_brightness)
                print(f"Ambient Light: {light_level:.2f} lux, LED Brightness: {led_brightness:.2f}%")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Clean up resources
        led_device.close()
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

