import smbus2
import time
import datetime
import json
import threading
import os
import gzip
import RPi.GPIO as GPIO  # Import RPi.GPIO library

# Define I2C addresses for the simulated sensors
SENSOR_ADDRESSES = [0x3B, 0x3C, 0x3D]

# Global variables for sensor data and log file
sensor_data = {addr: {'active_power': 0.0, 'voltage': 0.0, 'current': 0.0, 'frequency': 0.0, 'power_factor': 0.0} for addr in SENSOR_ADDRESSES}
log_file_path = None
log_file = None
log_file_lock = threading.Lock()
stop_event = threading.Event()

def simulate_sensor_reading(sensor_address):
    """Simulates reading data from a power sensor."""
    # Simulate sensor readings with realistic ranges
    active_power = 50 + (sensor_address - 0x3B) * 50  # Increase active power for each sensor
    voltage = 220 + (sensor_address - 0x3B) * 5  # Increase voltage for each sensor
    current = 0.2 + (sensor_address - 0x3B) * 0.1  # Increase current for each sensor
    frequency = 59.5 + (sensor_address - 0x3B) * 0.5  # Increase frequency for each sensor
    power_factor = 0.8 + (sensor_address - 0x3B) * 0.2  # Increase power factor for each sensor
    return active_power, voltage, current, frequency, power_factor

def acquire_sensor_data():
    """Acquires data from all simulated sensors in a loop."""
    while not stop_event.is_set():
        for sensor_address in SENSOR_ADDRESSES:
            try:
                active_power, voltage, current, frequency, power_factor = simulate_sensor_reading(sensor_address)
                sensor_data[sensor_address]['active_power'] = active_power
                sensor_data[sensor_address]['voltage'] = voltage
                sensor_data[sensor_address]['current'] = current
                sensor_data[sensor_address]['frequency'] = frequency
                sensor_data[sensor_address]['power_factor'] = power_factor
            except Exception as e:
                print(f"Error simulating sensor reading for address {sensor_address}: {e}")
        time.sleep(5)

def log_data_to_file():
    """Logs sensor data to a JSON file in the background."""
    global log_file, log_file_path
    while not stop_event.is_set():
        try:
            with log_file_lock:
                if log_file:
                    timestamp = datetime.datetime.now().isoformat()
                    data = {
                        'timestamp': timestamp,
                        'sensor_data': sensor_data
                    }
                    log_file.write(json.dumps(data) + '\n')
                    log_file.flush()  # Ensure data is written to disk immediately

                    # Check if the file size exceeds 1MB and compress it if necessary
                    log_file.seek(0, os.SEEK_END)  # Go to the end of the file
                    file_size = log_file.tell()
                    if file_size > 1024 * 1024:
                        log_file.close()
                        compress_log_file()
                        open_log_file() # Reopen the log file after compression

        except Exception as e:
            print(f"Error logging data to file: {e}")
            # Attempt to reopen the log file if it's not open
            if not log_file:
                open_log_file()
        time.sleep(1)

def open_log_file():
    """Opens or creates the log file with appropriate permissions."""
    global log_file, log_file_path
    today = datetime.date.today()
    log_file_path = f"energy_log_{today.year}-{today.month:02}-{today.day:02}.json"
    try:
        log_file = open(log_file_path, 'a', 0o600)  # 0o600 sets file permissions to owner read/write only
        if log_file.tell() == 0:  # Check if the file is empty to write the header
            log_file.write('[\n')
    except Exception as e:
        print(f"Error opening log file: {e}")
        log_file = None

def compress_log_file():
    """Compresses the log file and renames it with a timestamp."""
    global log_file_path
    timestamp = datetime.datetime.now().strftime("%H%M%S")
    compressed_file_path = f"energy_log_{datetime.date.today().year}-{datetime.date.today().month:02}-{datetime.date.today().day:02}_{timestamp}.json.gz"
    try:
        with open(log_file_path, 'rb') as f_in, gzip.open(compressed_file_path, 'wb') as f_out:
            f_out.writelines(f_in)
        os.remove(log_file_path)
        print(f"Log file compressed to {compressed_file_path}")
    except Exception as e:
        print(f"Error compressing log file: {e}")

def view_current_readings():
    """Prints the current sensor readings to the console."""
    print("Current Sensor Readings:")
    for addr, data in sensor_data.items():
        print(f"Sensor {addr}: Active Power = {data['active_power']:.2f} W, Voltage = {data['voltage']:.2f} V, Current = {data['current']:.2f} A, Frequency = {data['frequency']:.2f} Hz, Power Factor = {data['power_factor']:.2f}")

def view_data_for_date():
    """Prompts the user for a date and prints the data from that day."""
    date_str = input("Enter the date in YYYY-MM-DD format: ")
    try:
        date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
        file_name = f"energy_log_{date.year}-{date.month:02}-{date.day:02}.json"
        if os.path.exists(file_name):
            with open(file_name, 'r') as f:
                lines = f.readlines()
                for line in lines:
                    try:
                        data = json.loads(line)
                        if datetime.datetime.fromisoformat(data['timestamp'][:10]).date() == date:
                            print(f"{data['timestamp']}: {data['sensor_data']}")
                    except json.JSONDecodeError:
                        print(f"Skipping invalid JSON line: {line.strip()}")
        else:
            print(f"Data for date {date_str} not found.")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")

def view_min_max_avg_power():
    """Prompts the user for a date and prints the minimum, maximum, and average active power for each sensor."""
    date_str = input("Enter the date in YYYY-MM-DD format: ")
    try:
        date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
        file_name = f"energy_log_{date.year}-{date.month:02}-{date.day:02}.json"
        if os.path.exists(file_name):
            min_power = {addr: float('inf') for addr in SENSOR_ADDRESSES}
            max_power = {addr: float('-inf') for addr in SENSOR_ADDRESSES}
            total_power = {addr: 0.0 for addr in SENSOR_ADDRESSES}
            count = {addr: 0 for addr in SENSOR_ADDRESSES}

            with open(file_name, 'r') as f:
                lines = f.readlines()
                for line in lines:
                    try:
                        data = json.loads(line)
                        if datetime.datetime.fromisoformat(data['timestamp'][:10]).date() == date:
                            for addr, sensor_data in data['sensor_data'].items():
                                power = sensor_data['active_power']
                                min_power[addr] = min(min_power[addr], power)
                                max_power[addr] = max(max_power[addr], power)
                                total_power[addr] += power
                                count[addr] += 1
                    except json.JSONDecodeError:
                        print(f"Skipping invalid JSON line: {line.strip()}")

            print("Minimum Active Power:")
            for addr, power in min_power.items():
                print(f"Sensor {addr}: {power:.2f} W")

            print("\nMaximum Active Power:")
            for addr, power in max_power.items():
                print(f"Sensor {addr}: {power:.2f} W")

            print("\nAverage Active Power:")
            for addr, power in total_power.items():
                if count[addr] > 0:
                    avg_power = power / count[addr]
                    print(f"Sensor {addr}: {avg_power:.2f} W")
                else:
                    print(f"Sensor {addr}: No data for this date.")

        else:
            print(f"Data for date {date_str} not found.")
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")

def main_menu():
    """Displays the main menu and handles user input."""
    while True:
        print("\nEnergy Monitoring System")
        print("1. View Current Readings")
        print("2. View Data for Date")
        print("3. View Min/Max/Avg Power")
        print("4. Quit")

        choice = input("Enter your choice: ")

        if choice == '1':
            view_current_readings()
        elif choice == '2':
            view_data_for_date()
        elif choice == '3':
            view_min_max_avg_power()
        elif choice == '4':
            print("Exiting...")
            break
        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    try:
        # Initialize I2C bus (even though sensors are simulated)
        bus = smbus2.SMBus(1)  # Use 1 for Raspberry Pi 3 and later

        # Start the sensor data acquisition thread
        acquisition_thread = threading.Thread(target=acquire_sensor_data)
        acquisition_thread.daemon = True  # Allow the main thread to exit even if this thread is running
        acquisition_thread.start()

        # Start the log file writing thread
        log_thread = threading.Thread(target=log_data_to_file)
        log_thread.daemon = True
        log_thread.start()

        # Open the log file
        open_log_file()

        # Run the main menu
        main_menu()

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Clean up resources
        stop_event.set()  # Signal threads to stop
        if log_file:
            log_file.close()
        print("Program finished.")

