    try:
        # Initialize I2C bus (even though sensors are simulated)
        bus = smbus2.SMBus(1)  # Use 1 for Raspberry Pi 3 and later

        # Start the sensor data acquisition thread
        acquisition_thread = threading.Thread(target=acquire_sensor_data)
        acquisition_thread.daemon = True  # Allow the main thread to exit even if this thread is running
        acquisition_thread.start()

        # Start the log file writing thread
        log_thread = threading.Thread(target=log_data_to_file)
        log_thread.daemon = True
        log_thread.start()

        # Open the log file
        open_log_file()

        # Run the main menu
        main_menu()

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        # Clean up resources
        stop_event.set()  # Signal threads to stop
        if log_file:
            log_file.close()
        print("Program finished.")

