LISTEN_PORT = 9099
GPS_READ_TIMEOUT = 2.0

# Global flag to control the tracking state
tracking_state = 'stopped'

# Function to handle shutdown signals
def signal_handler(sig, frame):
    logging.info('Shutting down remote control server...')
    global gps_serial, gps_i2c
    if gps_serial:
