            parts = line.split(',')
            if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
                return {'lat': parts[0], 'lon': parts[1]}
            else:
                logging.warning(f"Invalid GPS data: {line}")
                return None
        elif gps_i2c:
            # Read from I2C (replace with actual I2C GPS reading logic)
            # Example: data = gps_i2c.read_i2c_block_data(0x42, 0x00, 10)
            # Example: lat = data[0] + data[1]/60.0 + data[2]/3600.0
            # Example: lon = data[3] + data[4]/60.0 + data[5]/3600.0
            # return {'lat': lat, 'lon': lon}
            logging.warning("I2C GPS reading not implemented")
            return None
        else:
            # Simulate GPS coordinates if no module is connected
            import random
            return {'lat': random.uniform(-90, 90), 'lon': random.uniform(-180, 180)}
    except Exception as e:
        logging.error(f"Error reading GPS position: {e}")
        return None

def handle_command(command):
    """Processes a remote control command and returns a response."""
    global tracking_state
    if command == 'start':
        tracking_state = 'running'
        logging.info("Tracking started")
        return json.dumps({'status': 'started'})
    elif command == 'stop':
        tracking_state = 'stopped'
        logging.info("Tracking stopped")
        return json.dumps({'status': 'stopped'})
    elif command == 'report':
        position = read_gps_position()
        if position:
            return json.dumps(position)
        else:
            return json.dumps({'error': 'No GPS data available'})
    else:
        return json.dumps({'error': 'Invalid command'})

