        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((LISTEN_HOST, LISTEN_PORT))
        server_socket.listen(1)
        logging.info(f"Remote control server listening on {LISTEN_HOST}:{LISTEN_PORT}")

        while True:
            # Accept a connection with a timeout
            server_socket.settimeout(1.0)
            try:
                client_socket, client_address = server_socket.accept()
                logging.info(f"Accepted connection from {client_address}")
                client_socket.settimeout(GPS_READ_TIMEOUT)

                # Receive the command
                try:
                    data = client_socket.recv(1024).decode('utf-8').strip()
                    if not data:
                        logging.warning("No data received")
                        client_socket.sendall(json.dumps({'error': 'No data received'}).encode('utf-8'))
                        continue

                    # Process the command
                    response = handle_command(data)
                    client_socket.sendall(response.encode('utf-8'))

                except socket.timeout:
                    logging.warning("Socket timeout")
                    client_socket.sendall(json.dumps({'error': 'Socket timeout'}).encode('utf-8'))

                except json.JSONDecodeError:
                    logging.warning("Invalid JSON data")
                    client_socket.sendall(json.dumps({'error': 'Invalid JSON data'}).encode('utf-8'))

                finally:
                    client_socket.close()

            except socket.timeout:
                # Continue listening even if no connection is accepted within the timeout
                pass

    except socket.error as e:
        logging.error(f"Socket error: {e}")
    finally:
        # Clean up resources
        if 'server_socket' in locals():
            server_socket.close()
        logging.info("Remote control server stopped.")

if __name__ == "__main__":
    main()

