from gpiozero import OutputDevice, Servo
import time

class Laser:
    def __init__(self, pin=17):
        try:
            self.laser = OutputDevice(pin, active_high=True, initial_value=False)
        except Exception as e:
            print(f"Laser Error: {e}")
            self.laser = None
    def on(self):
        if self.laser:
            self.laser.on()
    def off(self):
        if self.laser:
            self.laser.off()
    def close(self):
        if self.laser:
            self.laser.close()

class Aim:
    def __init__(self, hpin=18, vpin=19, ld=1.5, sd=0.75):
        try:
            self.laser = Laser()
            self.horz = Servo(hpin)
            self.vert = Servo(vpin)
            self.ld = ld
            self.sd = sd
            self.hp = [.2,.3,.6,.7,.8,.7,.6,.3,.2]
            self.vp = [.2,.3,.4,.5,.6,.7,.6,.5,.4,.3,.2]
        except Exception as e:
            print(f"Aim Error: {e}")
            self.laser = None

    def aim(self, nums):
        if not self.laser: return
        try:
            for i in sorted(range(1, len(nums)+1), key=lambda k: nums[k-1]):
                time.sleep(self.sd/2)
                self.horz.value = self.hp[i-1]
                self.vert.value = self.vp[i-1]
                time.sleep(self.sd/2)
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self.horz.value = .5 #return to center
                self.vert.value = .5
        except Exception as e:
            print(f"Aim Sequence Error: {e}")

if __name__ == "__main__":
    aim = Aim()
    nums = [2,4,6,7,8,9,10,11,12] # example sequence
    aim.aim(nums)

