import RPi.GPIO as GPIO
import time
import datetime

# Define the GPIO pin connected to the relay
RELAY_PIN = 17

# Define the sunrise and sunset times (24-hour format)
SUNRISE_TIME = datetime.time(7, 0)
SUNSET_TIME = datetime.time(19, 0)

def setup_gpio():
    """Sets up the GPIO pin for the relay."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT)
        print("GPIO setup successful.")
        return True
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        return False

def control_relay(state):
    """Controls the relay (HIGH = close, LOW = open)."""
    try:
        GPIO.output(RELAY_PIN, state)
        print(f"Relay set to {state}")
        time.sleep(1)  # Short delay to allow relay to activate
    except Exception as e:
        print(f"Error controlling relay: {e}")

def main():
    """Main function to control the chicken coop door."""
    if not setup_gpio():
        return  # Exit if GPIO setup failed

    try:
        while True:
            now = datetime.datetime.now().time()

            if SUNSET_TIME <= now:
                control_relay(GPIO.HIGH)  # Close the door
            elif SUNRISE_TIME >= now:
                control_relay(GPIO.LOW)   # Open the door

            time.sleep(60)  # Check every 60 seconds

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

