RELAY_ON_COMMAND = 'RELAY1 ON\n'
RELAY_OFF_COMMAND = 'RELAY1 OFF\n'

# Delay between relay state changes (seconds)
DELAY_SECONDS = 5

# Global variable to track serial port
serial_port = None

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info('Shutting down gracefully...')
    if serial_port:
        try:
            serial_port.close()
            logging.info('Serial port closed.')
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")
    sys.exit(0)

def initialize_serial():
    """Initializes the serial connection."""
    global serial_port
    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        logging.info(f"Serial port {SERIAL_PORT} initialized.")
    except serial.SerialException as e:
        logging.error(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred during serial initialization: {e}")
        sys.exit(1)

def send_relay_command(command):
    """Sends a command to the relay module."""
    try:
        if serial_port.write(command.encode()) != len(command):
            logging.warning("Incomplete write to serial port. Command not sent.")
        logging.info(f"Command sent: {command.strip()}")
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
    except Exception as e:
        logging.error(f"An unexpected error occurred while sending command: {e}")

def main_loop():
    """Main loop to control the relay."""
    try:
        while True:
            send_relay_command(RELAY_ON_COMMAND)
            time.sleep(DELAY_SECONDS)
            send_relay_command(RELAY_OFF_COMMAND)
            time.sleep(DELAY_SECONDS)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred in the main loop: {e}")
    finally:
        if serial_port:
            try:
                serial_port.close()
                logging.info('Serial port closed.')
            except Exception as e:
                logging.error(f"Error closing serial port: {e}")

if __name__ == "__main__":
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize serial communication
    initialize_serial()

    # Flush serial input buffer
    if serial_port:
        try:
            serial_port.flushInput()
            logging.info("Serial input buffer flushed.")
        except serial.SerialException as e:
            logging.error(f"Error flushing serial input buffer: {e}")
        except Exception as e:
            logging.error(f"An unexpected error occurred during serial flush: {e}")

    # Start the main loop
    main_loop()

