#!/usr/bin/env python3
# hydroponics_control.py
# A simple hydroponics control system for Raspberry Pi using gpiozero and TinyML.
# This script demonstrates basic intent recognition and actuator control.

import gpiozero
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins for actuators
PUMP_PIN = 20
LIGHT_PIN = 21

# Define intents
INTENTS = {
    "pump_on": PUMP_PIN,
    "pump_off": PUMP_PIN,
    "light_toggle": LIGHT_PIN,
    "light_on": LIGHT_PIN,
    "light_off": LIGHT_PIN
}

def initialize_actuators():
    """Initializes the gpiozero OutputDevices for the pump and light."""
    try:
        pump = gpiozero.OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
        light = gpiozero.OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
        return pump, light
    except Exception as e:
        logging.error(f"Error initializing actuators: {e}")
        return None, None

def parse_phrase(phrase):
    """Parses a phrase into an intent and optional parameters."""
    # Simple keyword-based intent recognition (case-insensitive)
    for intent, pin in INTENTS.items():
        if intent in phrase.lower():
            return intent, pin
    return None, None

def apply_intent(intent, pin, pump, light):
    """Applies the recognized intent to the actuators."""
    try:
        if intent == "pump_on":
            pump.on()
            logging.info("Pump turned ON")
        elif intent == "pump_off":
            pump.off()
            logging.info("Pump turned OFF")
        elif intent == "light_toggle":
            light.toggle()
            logging.info("Light toggled")
        elif intent == "light_on":
            light.on()
            logging.info("Light turned ON")
        elif intent == "light_off":
            light.off()
            logging.info("Light turned OFF")
        else:
            logging.warning(f"Unknown intent: {intent}")
    except Exception as e:
        logging.error(f"Error applying intent: {e}")

def main():
    """Main function to run the hydroponics control system."""
    pump, light = initialize_actuators()
    if pump is None or light is None:
        logging.error("Failed to initialize actuators. Exiting.")
        return

    test_phrases = [
        "turn the pump on",
        "switch the light",
        "turn pump off",
        "unknown command"  # This will log a warning
    ]

    try:
        for phrase in test_phrases:
            intent, pin = parse_phrase(phrase)
            if intent:
                apply_intent(intent, pin, pump, light)
            else:
                logging.warning(f"No intent recognized in: {phrase}")
            time.sleep(1)  # Small delay between commands

    except KeyboardInterrupt:
        logging.info("Exiting program due to keyboard interrupt.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure actuators are turned off on exit
        pump.close()
        light.close()
        logging.info("Actuators shutdown. Program finished.")

if __name__ == "__main__":
    main()

