    def get_supply_current(self):
        """Reads and returns the power supply current."""
        raw_value = self.read_word(5)
        if raw_value is None:
            return None
        return (raw_value / SUPPLY_VOLTAGE_CALIBRATION) * 1000

    def get_battery_current(self):
        """Reads and returns the battery current."""
        raw_value = self.read_word(7)
        if raw_value is None:
            return None
        return (raw_value / BATTERY_VOLTAGE_CALIBRATION) * 1000

    def get_temperature(self):
        """Reads and returns the temperature."""
        raw_value = self.read_word(9)
        if raw_value is None:
            return None
        return (raw_value / 256) - 273.15

    def get_full_battery_voltage(self):
        """Reads and returns the full battery voltage."""
        raw_value = self.read_word(11)
        if raw_value is None:
            return None
        return (raw_value / BATTERY_VOLTAGE_CALIBRATION) * 100

    def get_empty_battery_voltage(self):
        """Reads and returns the empty battery voltage."""
        raw_value = self.read_word(13)
        if raw_value is None:
            return None
        return (raw_value / BATTERY_VOLTAGE_CALIBRATION) * 100

    def get_battery_protection_voltage(self):
        """Reads and returns the battery protection voltage."""
        raw_value = self.read_word(15)
        if raw_value is None:
            return None
        return (raw_value / BATTERY_VOLTAGE_CALIBRATION) * 100

    def get_battery_remaining_capacity(self):
        """Reads and returns the battery remaining capacity."""
        raw_value = self.read_word(17)
        if raw_value is None:
            return None
        return (raw_value / BATTERY_VOLTAGE_CALIBRATION) * 100

    def get_sampling_period(self):
        """Reads and returns the sampling period."""
        return self.read_byte(19)

    def get_power_state(self):
        """Reads and returns the power state."""
        return self.read_byte(23)


class INA219Sensor(I2CDevice):
    """
    A class to represent the INA219 sensor.
    """

    def __init__(self, bus_number, device_address, shunt_resistor, name):
        super().__init__(bus_number, device_address, name)
        self.shunt_resistor = shunt_resistor
        self.sensor = None
        self.initialize_sensor()

    def initialize_sensor(self):
        """Initializes the INA219 sensor with retry logic."""
        for attempt in range(I2C_RETRY_COUNT):
            try:
                if self.name == "Supply INA219":
                    self.sensor = PiINA219(shunt_ohm=self.shunt_resistor, busnum=self.bus_number, address=self.device_address)
                else:
                    self.sensor = INA219(shunt_resistor=self.shunt_resistor, busnum=self.bus_number, address=self.device_address)
                self.sensor.configure()
                logging.info(f"{self.name} initialized successfully.")
                return  # Exit the loop if successful
            except Exception as e:
                logging.warning(f"Attempt {attempt + 1} to initialize {self.name} failed: {e}")
                if attempt < I2C_RETRY_COUNT - 1:
                    time.sleep(I2C_RETRY_DELAY)
        logging.error(f"Failed to initialize {self.name} after {I2C_RETRY_COUNT} attempts.")
        raise

    def get_voltage(self):
        """Reads and returns the bus voltage."""
        try:
            return self.sensor.voltage()
        except Exception as e:
            logging.error(f"Error reading voltage from {self.name}: {e}")
            return None

    def get_current(self):
        """Reads and returns the current."""
        try:
            return self.sensor.current()
        except DeviceRangeError:
            logging.warning(f"Current out of range for {self.name}.")
            return None
        except Exception as e:
            logging.error(f"Error reading current from {self.name}: {e}")
            return None

    def get_power(self):
        """Reads and returns the power."""
        try:
            return self.sensor.power()
        except Exception as e:
            logging.error(f"Error reading power from {self.name}: {e}")
            return None


def main():
    """
    Main entry point: reads and prints the UPS and INA219 data.
    """
    ups = UPSPlus(DEVICE_BUS, DEVICE_ADDRESS)
    supply_sensor = INA219Sensor(DEVICE_BUS, SUPPLY_INA219_ADDRESS, SUPPLY_SHUNT_RESISTOR, "Supply INA219")
    battery_sensor = INA219Sensor(DEVICE_BUS, BATTERY_INA219_ADDRESS, BATTERY_SHUNT_RESISTOR, "Battery INA219")

    try:
        while True:
            # Read and print UPS data
            supply_voltage = ups.get_supply_voltage()
            if supply_voltage is not None:
                logging.info("Supply Voltage: %.3f V", supply_voltage)

            battery_voltage = ups.get_battery_voltage()
            if battery_voltage is not None:
                logging.info("Battery Voltage: %.3f V", battery_voltage)

            supply_current = ups.get_supply_current()
            if supply_current is not None:
                logging.info("Supply Current: %.3f mA", supply_current)

            battery_current = ups.get_battery_current()
            if battery_current is not None:
                logging.info("Battery Current: %.3f mA", battery_current)

            temperature = ups.get_temperature()
            if temperature is not None:
                logging.info("Temperature: %.3f C", temperature)

            full_battery_voltage = ups.get_full_battery_voltage()
            if full_battery_voltage is not None:
                logging.info("Full Battery Voltage: %.3f V", full_battery_voltage)

            empty_battery_voltage = ups.get_empty_battery_voltage()
            if empty_battery_voltage is not None:
                logging.info("Empty Battery Voltage: %.3f V", empty_battery_voltage)

            battery_protection_voltage = ups.get_battery_protection_voltage()
            if battery_protection_voltage is not None:
                logging.info("Battery Protection Voltage: %.3f V", battery_protection_voltage)

            battery_remaining_capacity = ups.get_battery_remaining_capacity()
            if battery_remaining_capacity is not None:
                logging.info("Battery Remaining Capacity: %.3f %%", battery_remaining_capacity)

            sampling_period = ups.get_sampling_period()
            if sampling_period is not None:
                logging.info("Sampling Period: %d ms", sampling_period)

            power_state = ups.get_power_state()
            if power_state is not None:
                logging.info("Power State: %d", power_state)

            # Read and print INA219 data
            supply_voltage = supply_sensor.get_voltage()
            if supply_voltage is not None:
                logging.info("Supply Voltage: %.3f V", supply_voltage)

            supply_current = supply_sensor.get_current()
            if supply_current is not None:
                logging.info("Supply Current: %.3f mA", supply_current)

            supply_power = supply_sensor.get_power()
            if supply_power is not None:
                logging.info("Supply Power: %.3f mW", supply_power)

            battery_voltage = battery_sensor.get_voltage()
            if battery_voltage is not None:
                logging.info("Battery Voltage: %.3f V", battery_voltage)

            battery_current = battery_sensor.get_current()
            if battery_current is not None:
                logging.info("Battery Current: %.3f mA", battery_current)

            battery_power = battery_sensor.get_power()
            if battery_power is not None:
                logging.info("Battery Power: %.3f mW", battery_power)

            time.sleep(5)

    except KeyboardInterrupt:
        logging.info("Exiting...")
    finally:
        ups.close()
        supply_sensor.close()
        battery_sensor.close()


if __name__ == "__main__":
    main()

