import serial
import time
import pynmea2

# Configuration for the serial port
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'


def initialize_serial(port, baudrate, timeout):
    """Initializes the serial port."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def read_gps_data(serial_port):
    """Reads a line of data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def parse_gps_data(nmea_data):
    """Parses the NMEA data to extract latitude, longitude, and altitude."""
    if nmea_data.startswith('$GPGGA'):
        try:
            msg = pynmea2.parse(nmea_data)
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            fix_quality = msg.fix_quality
            return latitude, longitude, altitude, fix_quality
        except pynmea2.ParseError as e:
            print(f"Error parsing NMEA data: {e}")
            return None, None, None, None
    return None, None, None, None


def log_coordinates(latitude, longitude, altitude, log_file):
    """Logs the coordinates to a file with a timestamp."""
    timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
    try:
        with open(log_file, 'a') as file:
            file.write(f"{timestamp}, {latitude}, {longitude}, {altitude}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def display_coordinates(latitude, longitude):
    """Prints the current coordinates to the console."""
    print(f"Latitude: {latitude}, Longitude: {longitude}")


def main():
    """Main function to read, parse, and log GPS data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            nmea_data = read_gps_data(serial_connection)

            if nmea_data:
                latitude, longitude, altitude, fix_quality = parse_gps_data(nmea_data)

                if latitude is not None and longitude is not None and altitude is not None and fix_quality == 1:
                    log_coordinates(latitude, longitude, altitude, LOG_FILE)
                    display_coordinates(latitude, longitude)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

