# Reads heart rate and SpO2 from a pulse oximeter via UART on Raspberry Pi.

import serial
import time

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

def read_pulse_oximeter_data():
    """
    Reads heart rate and SpO2 data from the pulse oximeter.
    """
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        heart_rate, spo2 = line.split(',')
                        print(f'Heart Rate: {heart_rate} bpm, SpO2: {spo2} %')
                    time.sleep(1)
                except ValueError:
                    print(f"Warning: Invalid data format received: {line}")
                except Exception as e:
                    print(f"Error processing data: {e}")
                    break
    except serial.SerialException as e:
        print(f"Error: Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Exiting program.")

if __name__ == "__main__":
    read_pulse_oximeter_data()

