import json
import time
import serial
from threading import Thread
from flask import Flask, Response, request, jsonify, abort

# Initialize Flask application
app = Flask(__name__)

# Serial port configuration (adjust as needed)
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Global data store
DATA_STORE = [{"id": 1, "name": "CHIPS", "done": False}, 
              {"id": 2, "name": "garden", "done": False}]

# Lock for thread-safe access to the data store
data_lock = dict(lock=False)


def get_serial_connection():
    """Establishes a serial connection with the SCPI device."""
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None


def close_serial_connection(ser):
    """Closes the serial connection."""
    if ser and ser.is_open:
        ser.close()


def send_scpi_command(ser, command):
    """Sends an SCPI command to the device and returns the response."""
    try:
        ser.write(f'{command}\n'.encode())
        time.sleep(0.1)  # Allow time for the device to process
        response = ser.read_all().decode()
        return response
    except serial.SerialException as e:
        print(f"Error communicating with serial port: {e}")
        return None


def get_instrument_identity(ser):
    """Retrieves the instrument identity string."""
    response = send_scpi_command(ser, '*IDN?')
    if response:
        return response.strip()
    return None


def get_data_store():
    """Retrieves the current data store contents."""
    with data_lock:
        data_lock['lock'] = True  # Acquire lock
        data_copy = DATA_STORE.copy()  # Create a copy to prevent modification
        data_lock['lock'] = False # Release lock
        return json.dumps(data_copy)


def add_data_item(item_id, name, done):
    """Adds a new item to the data store."""
    with data_lock:
        data_lock['lock'] = True # Acquire lock
        new_item = {"id": item_id, "name": name, "done": bool(done)} # Ensure boolean for 'done'
        DATA_STORE.append(new_item)
        data_lock['lock'] = False # Release lock
    return jsonify(DATA_STORE[-1]), 201


def get_data_item(item_id):
    """Retrieves a specific item from the data store."""
    with data_lock:
        data_lock['lock'] = True # Acquire lock
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        data_lock['lock'] = False # Release lock
        if item:
            return jsonify(item)
        else:
            abort(404, description="Item not found")


@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Retrieves the instrument version information."""
    ser = get_serial_connection()
    if not ser:
        return Response("Serial port connection failed", status=503, mimetype='text/html')

    try:
        identity = get_instrument_identity(ser)
        if identity:
            response = f"Instrument Version: {identity}"
        else:
            response = "Failed to retrieve instrument version"
        return Response(response, mimetype='text/html')
    except Exception as e:
        print(f"Error getting version: {e}")
        return Response(f"Error: {e}", status=500, mimetype='text/html')
    finally:
        close_serial_connection(ser)


@app.route('/getdata', methods=['GET'])
def get_json_data():
    """Retrieves the entire data store as JSON."""
    return Response(get_data_store(), mimetype='application/json')


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set_item(item_id):
    """Retrieves a specific item from the data store."""
    return get_data_item(item_id)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def get_post_item(item_id, name):
    """Creates a new item and adds it to the data store."""
    ser = get_serial_connection()
    if not ser:
        return Response("Serial port connection failed", status=503, mimetype='text/html')

    try:
        response, status = add_data_item(item_id, name, False)
        return response
    except Exception as e:
        print(f"Error adding item: {e}")
        return Response(f"Error: {e}", status=500, mimetype='text/html')
    finally:
        close_serial_connection(ser)


@app.route('/postjson', methods=['POST'])
def post_json_data():
    """Handles POST requests with JSON data."""
    try:
        if "application/json" in request.headers.get("Content-Type", ""):
            new_item = request.get_json()
        elif "application/x-www-form-urlencoded" in request.headers.get("Content-Type", ""):
            new_item = request.form.to_dict()
        else:
            return Response("Invalid Content-Type", status=400, mimetype='text/html')

        ser = get_serial_connection()
        if not ser:
            return Response("Serial port connection failed", status=503, mimetype='text/html')

        item_id = DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1
        name = new_item.get('name', '')
        done = bool(new_item.get('done', False))

        response, status = add_data_item(item_id, name, done)
        return response

    except Exception as e:
        print(f"Error posting data: {e}")
        return Response(f"Error: {e}", status=500, mimetype='text/html')
    finally:
        close_serial_connection(ser)


if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

